def balanced(s: str) -> bool:
    """Return whether all brackets in *s* are balanced, ignoring quoted text."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack: list[str] = []
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            in_string = True
        elif char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != pairs[char]:
                return False

    return not in_string and not stack
